text:
Here's a simple water tracker with a goal of 8 glasses. Tap + to add a glass, − to undo one. It saves your count for today and starts fresh tomorrow.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:24px;text-align:center;background:#f2f8fc;color:#123}
h1{font-size:20px;margin:0 0 4px}
#d{font-size:13px;color:#567;margin-bottom:16px}
#c{font-size:48px;font-weight:600;margin:8px 0}
#bar{height:14px;background:#d8e8f2;border-radius:7px;max-width:320px;margin:0 auto 16px;overflow:hidden}
#fill{height:100%;width:0;background:#2a8ad8;transition:width .3s}
#g{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;max-width:320px;margin:0 auto 20px}
.gl{width:60px;height:60px;border-radius:8px;border:2px solid #2a8ad8;background:#fff;font-size:26px;line-height:56px}
.gl.on{background:#2a8ad8}
button{font-size:22px;width:56px;height:56px;border-radius:28px;border:0;background:#2a8ad8;color:#fff;margin:0 8px;cursor:pointer}
button.m{background:#9bb8cc}
#msg{margin-top:16px;font-size:15px;min-height:20px}
</style></head><body>
<h1>Water today</h1>
<div id="d"></div>
<div id="c">0 / 8</div>
<div id="bar"><div id="fill"></div></div>
<div id="g"></div>
<button class="m" onclick="chg(-1)" aria-label="Remove a glass">−</button>
<button onclick="chg(1)" aria-label="Add a glass">+</button>
<div id="msg"></div>
<script>
var GOAL=8,key="water-"+new Date().toISOString().slice(0,10),n=0;
try{n=parseInt(localStorage.getItem(key)||"0",10)||0}catch(e){}
document.getElementById("d").textContent=new Date().toDateString();
function chg(x){n=Math.max(0,n+x);try{localStorage.setItem(key,n)}catch(e){}draw()}
function draw(){
document.getElementById("c").textContent=n+" / "+GOAL;
document.getElementById("fill").style.width=Math.min(100,n/GOAL*100)+"%";
var h="";for(var i=0;i<GOAL;i++)h+='<div class="gl'+(i<n?' on':'')+'">'+(i<n?'💧':'')+'</div>';
document.getElementById("g").innerHTML=h;
document.getElementById("msg").textContent=n>=GOAL?"Goal reached. Well done!":(GOAL-n)+" more to go";
}
draw();
</script></body></html>
```
